"""Build the English design guides from the editorial translation below.

The canonical API/schema/SQL files remain in site/prd/engineering/contracts.
This builder does not change their identifiers, schema versions, or semantics.
"""
from pathlib import Path
import html, json

HERE = Path(__file__).resolve().parent
EN = HERE.parent
SITE = EN.parent
E = html.escape
source_prd = json.loads((SITE / 'prd/prd.json').read_text())
source_req = json.loads((SITE / 'prd/requirements.json').read_text())
source_handbook = json.loads((SITE / 'engineering/handbook.json').read_text())

def p(t): return '<p>' + E(t) + '</p>'
def ul(items): return '<ul>' + ''.join('<li>'+E(i)+'</li>' for i in items) + '</ul>'
def table(headers, rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+E(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def link(url,label): return '<a href="'+E(url,quote=True)+'">'+E(label)+'</a>'
def section(sid,title,body): return {'id':sid,'title':title,'body':body}
def page(folder, filename, title, lead, sections, original, subtitle='English design edition · 14 November 2026'):
    target = EN/folder/filename
    target.parent.mkdir(parents=True, exist_ok=True)
    nav='<nav aria-label="Collection navigation">'+ ''.join(link(u,t) for u,t in [('../index.html','Home'),('../papers/','Papers'),('../projects/','Projects'),('../prd/','PRD'),('../architecture/','Architecture'),('../engineering/','Engineering'),('../learn/','Learning path')])+'</nav>'
    toc='<nav class="toc" aria-label="On this page"><h2>On this page</h2><ol>'+''.join('<li>'+link('#'+s['id'],s['title'])+'</li>' for s in sections)+'</ol></nav>'
    content=''.join('<section id="'+E(s['id'])+'"><h2>'+E(s['title'])+'</h2>'+s['body']+'</section>' for s in sections)
    status='Proposed design, not a deployed production Agent. Existing offline exercises demonstrate only their stated fixed workflows or simulated policies.'
    target.write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+E(title)+' · Structural Biology Agent Resources</title><link rel="stylesheet" href="../style.css"><script defer src="../common.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="page-header">'+nav+'<p class="eyebrow">'+E(subtitle)+'</p><h1>'+E(title)+'</h1>'+p(lead)+p('Author: Yi Zhou (周熠)')+'</header><main id="main" class="content" style="max-width:1180px"><aside class="notice">'+E(status)+'</aside>'+toc+content+'</main><footer>'+p('English editorial edition of the current source material. Contract identifiers and machine-readable specifications retain their original version.')+link(original,'Original Chinese document')+' · '+link('../index.html','English collection')+'</footer></body></html>')

FR = [
('Project and task identity','Create a stable task_id and immutable original-request TaskRevision. Preallocate an ANALYZE Run while the candidate specification is still DRAFT; freeze the original request, inputs, model configuration, trusted scope and total budget. Intent parsing, clarification, planning, repair, tools and reporting belong to this same Run. Reject unauthorized creation; deduplicate repeated requests.'),
('Controlled input import','Validate source, size, actual format and access. Store immutable original bytes with SHA-256 and acquisition metadata. Download only from configured sources. Reject empty responses, HTML error pages, unsupported formats and unclear permission; never silently replace the file.'),
('Object inventory and preprocessing','List model/entity, author and label chain identities, residue and atom counts, insertion codes, missing data and alternate conformers. Record before/after selection changes and whether ligands, waters and ions participate. Stop affected calculations if identity cannot be explained.'),
('Natural language to TaskSpec','Within the preallocated Run, derive the goal, objects, selections, fit/evaluation regions, contact definition, units, outputs and constraints. Preserve candidate provenance. Before the first scientific computation, programmatically check and freeze one FrozenTaskSpec with frozen_spec_id; every formal plan references that identity.'),
('Necessary clarification and revision','Ask only questions that change scientific meaning. Before freezing, append answers to the same Run without rewriting the original request, extending its deadline or resetting its budget. After freezing, a changed goal, object, selection or method creates a linked new TaskRevision and Run; preserve all old costs and unresolved state.'),
('Available capability catalogue','Expose scientific purpose, preconditions, typed I/O, version, resource class and validated range. Keep registration, deployment health, reference-test passage and current authorization separate. A declared interface alone is not READY and must not be offered as executable.'),
('Dependency planning and preflight compilation','The model proposes typed steps, dependencies, expected artifacts, validation nodes and stop conditions under the same frozen specification. Deterministically reject cycles, missing references, incompatible types, failed scientific preconditions, denied access and excessive budgets. A PlanRevision may change execution strategy within the same contract, not the scientific question.'),
('Selections and cross-structure mapping','Materialize one-to-one atom pairs while retaining author/label namespaces and insertion codes. A frozen sequence correspondence rule may propose the mapping, but expose coverage, conflicts, missing residues and unmatched items. Empty selections, duplicate pairs or unresolved ambiguity block fitting.'),
('Superposition and regional comparison','Compute the specified right-handed rigid transform, evaluation-region RMSD and per-pair displacement. Distinguish full-chain fitting, independent fits per region and evaluation after a fixed CORE fit. Record atom pairs and exclusions; do not silently trim outliers. Reject degeneracy, non-finite values and unsupported units.'),
('Geometric contacts','Use the frozen object identities, heavy-atom selection, Euclidean-distance threshold and explicit < or ≤ rule. Return atom pairs and separately deduplicated residue summaries. Do not promote distance contacts into hydrogen bonds, affinity or functional causation without the required evidence.'),
('Controlled real execution','Run fixed adapters in restricted Worker environments, with read-only inputs, dedicated outputs and enforced process/network/resource limits. Persist actual Step/Attempt execution facts. Ordinary new immutable artifacts within an authorized project are automatically allowed; the model cannot invent successful files.'),
('Bounded retries and scientific repair','Retry only safe transient failures within limits. Append diagnosed PlanRevisions and Attempts under the same FrozenTaskSpec and remaining Run budget. Preserve the goal, acceptance rules, all failed candidates and all costs. Stop when exhausted, stalled, denied or unrecoverable; never relax a threshold merely to obtain a pass.'),
('Query, cancellation and recovery','Use server-side facts as the authority; closing a page does not remove the Run. Separate a cancellation request from confirmed termination. Reconcile actual processes/jobs and existing artifacts before resubmitting. Preserve UNKNOWN when the side effect cannot be established.'),
('Execution and scientific acceptance','Record execution status independently from scientific_status. Check identity, mapping, units, schema, numerical invariants or independent references, and report citations. Successful process exit does not establish scientific acceptance. Invalid candidates may be shown only with explicit diagnostic labels.'),
('Evidence report and analytical views','P0 provides object/mapping tables, metrics, displacement/contact plots and auditable selection manifests. Optional read-only Mol* 3D highlighting is P1. Report the question, objects, method, results, evidence, limits and unfinished parts; populate numerical values from validated artifacts.'),
('Immutable artifacts and downloads','Automatically save authorized new project outputs and allow downloads within the same access policy. A reproducibility bundle records input identities, frozen specification, parameters, versions, artifacts and checks. Including original inputs depends on data rights; reject corrupted, missing or no-longer-authorized downloads.'),
('High-impact actions and approval','P0 keeps arbitrary code, export, overwriting and real HPC submission disabled rather than displaying nonfunctional approval controls. P1 approval binds the exact actor, project, input hashes, destination, parameters, versions, expiry and one-time use. Approval cannot expand hard permissions, support scope or cumulative hard budget.'),
('Identity, projects and data boundaries','A team pilot needs real server-side authentication and per-object authorization across storage, retrieval, state, caches, streams and download. Apply separate policies to private coordinates sent to a model, traces and exports. Model-supplied roles or tenant names confer no authority; connectors keep credentials server-side.'),
('Trace, cost and error ledger','From Run creation, retain parsing, clarification, planning, execution, validation and reporting events, structured failures, retries, both outcome types and cumulative resource use. Break down model/tool/failure/retry costs. Mark missing billing UNKNOWN rather than zero; minimize and redact sensitive diagnostics.'),
('Model configuration and planner adapter','Use a provider-neutral Planner/ModelAdapter and one initial production configuration. Freeze model/prompt settings before the Run. All model calls, including intent parsing, belong to it. Missing credentials, quota or network must produce an explicit failure; fixed-plan reference mode is visibly separate.'),
('Reproduction and version freeze','Publish a machine-readable manifest distinguishing deterministic computations from stochastic model/search choices. Freeze or identify inputs, tool/environment/checker versions and tolerances. Disclose hosted components that cannot be frozen; identify missing material instead of claiming complete reproduction.'),
('Capability packaging and release','Ship purpose, preconditions, schemas, limits, adapter, error codes, independent checks, reference tasks and reporting rules together. Enable a capability only after contract, numerical, permission and existing-regression checks pass. Registration is not deployment.'),
('Regression and real-model evaluation','First test contracts, numerics and deterministic execution; then test real-model object interpretation, planning, artifacts, explanations, refusal and total cost. Freeze the final test set. Missing Run artifacts remain failures; a broken global reference/scorer makes the evaluation INVALID, rather than making every model answer wrong.'),
('Feedback and failure triage','Link feedback to an accessible Run, frozen contract and relevant Attempt/artifact/report version. Creation is NEEDS_REPRODUCTION. Authorized reproduction and scientific review append REPRODUCED, DISPUTED or resolution evidence; confirmed defects link a regression task and fix version. Likes and model self-assessment do not become scientific truth.')
]
AC = [
('Input and specification contracts','Round-trip valid normalized selections; append pre-freeze clarification within one Run; bind frozen_spec_id before scientific execution. Invalid, unknown or non-finite parameters never reach scientific tools.'),
('Unambiguous structural identity','Preserve model, instance, namespace, mapping, counts, exclusions and input hash. Similar numbering or finite output cannot rescue a wrong object.'),
('Superposition and reference frames','Agree with a pre-frozen independent reference within tool-specific tolerances. Record R/t convention, fit region F, evaluation region E and det(R)>0. The AdK full-chain value near 7.130700 Å is one regression fixture only.'),
('Recomputable contact definition','Match atom-pair counts and deduplicated residue counts separately, including units and threshold convention. Do not infer affinity or hydrogen bonds from proximity alone.'),
('A checker cannot certify itself','Block all injected critical defects from trusted delivery. Disclose shared code/reference dependencies between the runtime validator and external acceptance; add independent recalculation for shared critical logic.'),
('Real-model end-to-end completion','Meet frozen quality goals using actual model-selected actions and actual observations. Keep all versions, Attempts, failures and costs. Fixed plans and mock models do not satisfy this gate.'),
('Ambiguous, invalid and unsupported tasks','Ask only decisive questions; apply documented defaults transparently; never invent a capability or silently substitute the goal. Score expected handling against frozen labels.'),
('Complete denominators and cost','Missing artifacts count as failed Runs. Retries add Attempts and cost, not independent samples. Report UNKNOWN costs and coverage. Corrupted global references produce INVALID_EVALUATION.'),
('Normal outputs proceed automatically','Authorized new project artifacts and same-permission downloads require no extra approval. Overwrite/export actions cannot masquerade as normal output, and approval cannot enable disabled P0 actions.'),
('Real authentication and project isolation','Derive actor/project from a trusted server session and authorize every resource. Block cross-project reads, writes and cache borrowing; revoke new access when a session or membership is withdrawn.'),
('Untrusted data cannot grant capability','Retrieved text cannot alter permissions, registry, budgets or approvals. Keep legitimate branches usable when rejecting an unrelated action. Measure task utility and actual unauthorized effects separately.'),
('Fixed execution entry points and effective isolation','No arbitrary shell/eval. Enforce read-only inputs, a dedicated output root, no host credentials, network/resource restrictions and process cleanup. Test path-resolution races, not just strings.'),
('Atomic cumulative budget','The server defines costs and hard limits. Reserve before each action and settle actual use across the entire Run. Resume/replanning cannot reset limits or hide costs; approval cannot override them.'),
('Stable identities through retry and recovery','Reuse the same operation for the same authenticated scope, idempotency key and payload digest; conflict on changed payload. Preserve every Attempt and prevent duplicate accepted publication.'),
('Cancellation and UNKNOWN reflect execution facts','Do not claim termination at request time. Reconcile uncertain effects before resubmission and settle resources after actual process/job cleanup. P0 does not claim verified Slurm recovery.'),
('Exact high-impact approval','Expire approval when a critical field changes; validate approver authority and consume it once. A digest alone grants no authority. Ordinary new reports do not need approval.'),
('Credentials and data minimization','Inject credentials only in controlled connectors. Exclude them from model context, reports, URLs and normal logs. Private model-bound data must satisfy project policy.'),
('Readable and injection-safe reports','Show objects, selections, method, units, results, evidence, exclusions and limits. Clearly label inconclusive science. Escape uploaded text/scripts and expose only authorized completed data.'),
('Complete provenance and replay','Link original TaskRevision, candidate/clarification events, FrozenTaskSpec, PlanRevision and Attempt; retain all critical versions/hashes. Same-contract repair shares a Run; changed science creates a linked new Run. Preserve validation history.'),
('Extensions preserve existing capabilities','Require scientific purpose, preconditions, I/O, permissions, resource/error semantics, validators and reference tasks. Do not offer an unvalidated capability as READY; prevent severe old-task regressions.'),
('Feedback, release and rollback are exercisable','Version code/images/configuration/references and acceptance evidence. Stop on severe scientific error, unauthorized effects or major regressions. Preserve feedback history and in-flight versions; a FIXED issue needs regression/fix references and cannot rewrite old scientific outcomes.'),
('Performance only under declared load','Calibrate and freeze SLOs and hardware after the pilot. P95 acceptance/query latency ≤2 s is a candidate target, excluding model inference and scientific completion; it is not a measured capacity claim.')
]
assert len(FR)==24 and len(AC)==22
requirements=[]
for i,((title,body),source) in enumerate(zip(FR,source_req['requirements']),1):
    requirements.append({'id':source['id'],'priority':source['priority'],'title':title,'requirement':body,'acceptance_ids':source['acceptance_ids']})
acceptance=[{'id':f'AC-{i:02d}','title':t,'pass_rule':b} for i,(t,b) in enumerate(AC,1)]

entities = [
('Project / Membership','Trusted identity, project membership and role','All reads, caches, events and downloads recheck current membership.'),
('Task / TaskRevision','Stable task plus immutable original-request revision','Clarification is an appended Run event. A changed frozen scientific question creates a linked revision and Run.'),
('Run','Preallocated complete analysis episode','Freeze request, inputs, configuration, scope and cumulative budget at creation. Do not create separate planning Runs to reset cost.'),
('FrozenTaskSpec','One immutable scientific definition per analysis Run','Bind before the first scientific TOOL operation. All formal plans, results and validations reference the same frozen_spec_id.'),
('Plan / Step','Immutable versioned dependency plan and logical operations','Compile types, references, DAG, preconditions and authorization. Revisions preserve the frozen scientific contract.'),
('Attempt','An actual MODEL, PREFLIGHT or TOOL execution','Persist operation_id, plan/step binding where required, lease_epoch, actual usage and outcome. A retry is a new Attempt within the same Run.'),
('Job','An external backend execution object reserved for P1','Identify by backend and external job ID plus stable operation correlation. Scheduler disappearance is not terminal-state proof.'),
('Artifact','Immutable input or derived bytes plus provenance','Bind SHA-256, size, media type, project and actual producing Attempt or control event. The model sees artifact IDs, never host paths.'),
('Validation','An appended checker/policy result for an artifact','Bind Run, frozen specification, checker/policy versions, measurements and ACCEPTED/REJECTED/INCONCLUSIVE outcome.'),
('RunEvent / Outbox','Ordered durable facts and pending notifications','Commit state and event atomically. A stream is a projection; network delivery may duplicate.'),
('RunScope / BudgetReservation','Server-derived authorization and resource reservation','Reserve atomically before dispatch, retain unknown liabilities and settle observed usage. Client estimates never grant authority.'),
('ActionIntent / Approval','Reserved exact high-impact action and approval records','P1 only: current approver authority, expiry/revocation, exact binding and atomic one-time consumption.'),
('FeedbackIssue','Versioned user report and reproduction history','Start NEEDS_REPRODUCTION; access-check every reference. Reproduction and domain judgment require authorized evidence.')
]

scope_rows=[
('Object retrieval and identity','Authorized PDB/mmCIF; model/chain/residue/atom/altloc inventory and hashes','Controlled sources, assemblies, batches and additional modalities'),
('Mapping and superposition','Supported protein Cα selections, explicit one-to-one mapping, separate fit/evaluation sets, RMSD/displacements','Complex correspondences, domains, retrieval and multi-structure comparison'),
('Geometric contacts','Explicit heavy-atom objects, atom pairs and residue summaries','SASA/buried area, richer interface methods and condition-aware statistics'),
('Quality and experimental support','Input/object/numerical integrity only','Geometry, confidence and experimental map/model validation as distinct capability packages'),
('Trajectories and ensembles','Recognize unsupported input and explain requirements','Topology/PBC/units/sampling contracts, convergence, uncertainty and ensemble analysis'),
('Prediction, docking and design','No P0 claim to run these methods','Versioned adapters with license, resource, applicability and independent acceptance evidence'),
('Execution backends','Restricted CPU Worker and persistent state','Controlled long jobs, HPC/GPU and batches after real backend recovery tests'),
('Reporting and review','Evidence-bound tables, plots, artifacts, downloads and feedback','Optional 3D viewers, expert workflows and controlled cross-project reuse')
]

api_labels=[
'List accessible projects','Upload and register immutable input','Request controlled RCSB import','Create original TaskRevision','Read task and Run summaries','Append clarification or fork a changed contract','Preallocate a complete Run','Read immutable compiled plan','Resume an allowed wait state','Read authoritative Run snapshot','Replay and stream durable events','Request cancellation','List accessible Run artifacts','Download immutable artifact','Read evidence report or PENDING state','List executable capability versions','P1 reserved: approve an exact action','Create feedback requiring reproduction','Query asynchronous import','Create original-request revision with CAS','Read feedback and maintenance evidence','Append reproduction/dispute/resolution history']
api_rows=[[x['id'],x['method']+' '+x['path'],api_labels[i],x['phase']] for i,x in enumerate(source_prd['architecture']['apis'])]

prd_sections=[
section('overview','Purpose, status and product unit',p('The product turns a natural-language structural-analysis question into an executable scientific task with explicit objects, constrained parameters and independent acceptance. Its unit is the task, frozen specification, Run and evidence bundle; a chat message is an input or explanation surface, not the authoritative execution record.')+p('This is the English edition of the proposed PRD 0.2 and current contract baseline. Publishing these documents does not deploy an Agent. The existing AdK offline teaching package performs four real coordinate operations under a fixed plan without a real model. The policy exercise covers synthetic/mock decisions, not real authentication, sandbox isolation or distributed quotas. Neither establishes open-ended planning or cross-family generalization.')+p('Researchers need reviewable results; tool maintainers need versioned capability packages; scientific reviewers need provenance; operators need budgets, permission boundaries and recoverable state. A usable first release must complete one real, inspectable scientific task and preserve its failures as well as its results.')),
section('scope','P0 boundary and long-term task space',p('General-purpose means that new scientific capabilities enter through versioned contracts, adapters, validators and reference tests. P0 is a bounded CPU coordinate-analysis slice; broad task maps are the extension goal, not a claim that every method is already installed or validated.')+table(['Task family','P0 commitment','Later extension, separately accepted'],scope_rows)+p('P0 excludes arbitrary shell or generated code, software installation, unrestricted URLs or data export, original-file overwrite, real Slurm/GPU submission, distributed multi-Agent control, de novo biological design and wet-lab operation. It must identify unsupported goals and explain a feasible next step without fabricating tool output.')),
section('journeys','User journeys and interface',table(['Journey','Required behavior','Definition of done'],[
('Explicit comparison','Inspect 4AKE/1AKE inputs, bind chain/model identity, compute full-chain and CORE-referenced regional Cα results, validate and report automatically.','Input hashes, mapping, transformations, units, plots and limitations agree; static coordinates do not establish a dynamic mechanism.'),
('Ambiguous objects','List genuine chains/models and ask decisive questions within the same Run before freezing.','The selected scientific object follows the user or an explicit accepted rule; no hidden default replaces it.'),
('Transient failure or closed page','Keep durable Run/Attempt history, retry only safe transient errors and reconcile before recovery.','The reopened UI shows authoritative execution and scientific outcomes, not a new accidental submission.'),
('Unsupported/high-impact action','Reject the unsupported action while preserving legitimate branches.','No fake approval enables disabled capabilities; the report explains partial or unsupported outcomes.'),
('Feedback','Link the issue to accessible Run and report versions, then request authorized reproduction.','NEEDS_REPRODUCTION, REPRODUCED, DISPUTED and resolution history remain auditable.')])+p('The workbench shows project identity, supported scope and tasks. The task view separates conversation, real object inventory, candidate/frozen specification, plan, budget and state. The results view separates execution from scientific status and shows all Attempts, mapping/metric plots, evidence and download. An administrative view controls capability and model availability; a front-end role label never authorizes access.')),
section('lifecycle','One Run, one frozen scientific contract',ul([
'Create immutable original TaskRevision and authorized input references. Preallocate ANALYZE Run and reserve its cumulative budget before model work.',
'Run fixed registered PREFLIGHT inspection, then model interpretation and necessary clarification. MODEL and allowed PREFLIGHT Attempts may precede a frozen specification; ordinary scientific TOOL Attempts may not.',
'Programmatically freeze FrozenTaskSpec once before scientific computation. It defines objects, selections, mapping/method intent, units, outputs and acceptance policy.',
'Ask the model for PlanCandidate; compile references, types, DAG, scientific preconditions, allowed tools, access and remaining budget. Persist the immutable accepted plan before dispatch.',
'Restricted Workers execute actual operations and publish verified immutable artifacts. Independent validators assess scientific quality. The controller may make bounded same-contract PlanRevisions using real observations.',
'Generate an evidence report or explicit rejected/inconclusive outcome. Record parsing, clarification, repair, execution and reporting costs under this same Run.',
'A post-freeze change in scientific goal, object, selection or method creates a linked new TaskRevision and Run. Old history, costs and UNKNOWN effects remain; ordinary retries do not become new independent evaluation samples.'
])+p('Clarification resolves scientific intent. Approval controls an exact high-impact side effect. They are different workflows. Already authorized normal parsing, computation, new immutable reports and same-permission downloads proceed automatically.')),
section('requirements','Functional requirements FR-01–FR-24',table(['ID / priority','Requirement','Behavior and boundary','Acceptance links'],[[x['id']+' / '+x['priority'],x['title'],x['requirement'],', '.join(x['acceptance_ids'])] for x in requirements])),
section('architecture','Implementation and entity ownership',p('Use one source repository and one LangGraph controller, a PostgreSQL business ledger and a restricted CPU Worker. API, controller and compute processes may restart independently. A React/TypeScript workbench and FastAPI/Pydantic contracts are proposed implementation choices; adapting the front end must preserve API and scientific contracts.')+p('Use Gemmi for structural inventory and a tested NumPy numerical kernel behind versioned adapters. The Bio.PDB teaching implementation is a migration/reference comparison, not a second default production parser. Low-throughput scheduling initially uses database transactions, leases and an outbox; Redis/Celery/Kafka are not P0 requirements.')+table(['Entity','Meaning','Invariant'],entities)+p('Store graph checkpoints separately from authoritative business facts, even if both use PostgreSQL. LangGraph checkpointing cannot guarantee exactly-once external side effects. The Worker requires read-only input mounts, dedicated outputs, no host secrets/control sockets, restricted network and enforced CPU/memory/process/disk/time limits. Verify these controls on the target environment.')),
section('contracts','Canonical contracts and API inventory',p('The following are the existing machine-readable contracts, not a second English API version. Schema validity, scientific validity and authorization remain separate gates. TaskSpec carries no credentials, host paths or authority-granting role; requested limits do not override server-derived RunScope.')+ul([])+ '<p>'+ ' · '.join(link(u,t) for u,t in [('../../prd/engineering/contracts/openapi.json','Canonical OpenAPI'),('../../prd/engineering/contracts/worker-protocol.schema.json','Worker protocol schema'),('../../prd/engineering/contracts/001_core.sql','Database migration'),('../../prd/engineering/contracts/capability.schema.json','Capability schema'),('../../prd/engineering/contracts/task_spec.example.json','TaskSpec example'),('../../prd/engineering/contracts/worker-preflight.example.json','PREFLIGHT example'),('../../prd/engineering/contracts/worker-dispatch.example.json','TOOL dispatch example'),('../../prd/engineering/contracts/result_manifest.example.json','Result manifest'),('../../prd/engineering/engineering-contracts-v0.2.zip','Contract bundle')])+'</p>'+table(['ID','Method and route','Purpose','Phase'],api_rows)+p('Creation/update requests bind an Idempotency-Key to principal, project, method, resource and canonical payload digest. Identical key plus payload reuses identity; changed payload conflicts. Recheck current authorization even when returning a cached response. Use expected revision/state version for compare-and-swap updates. A query returning HTTP 200 means the resource was read successfully; its scientific result may still be REJECTED or INCONCLUSIVE.')+p('SSE is a replayable projection of durable RunEvent records, not an execution channel. Cursor run_uuid:seq must match the Run; clients deduplicate by event_id. A stale retained cursor needs a snapshot/recovery response, and loss of the stream does not cancel computation. See canonical OpenAPI for exact response schemas and status codes.')),
section('runtime','State, budgets and uncertain execution',table(['Axis','States / interpretation'],[
('Specification','DRAFT, NEEDS_CLARIFICATION, FROZEN, DISCARDED. Only a frozen checked scientific contract authorizes ordinary scientific TOOL work.'),
('Run phase','INSPECTING, SPECIFYING, PLANNING, EXECUTING, VALIDATING, REPORTING. Phase is independent from execution status.'),
('Execution','QUEUED, RUNNING, WAITING_INPUT, WAITING_APPROVAL, RECONCILING, CANCEL_REQUESTED, UNKNOWN, COMPLETED, FAILED, CANCELLED.'),
('Science','NOT_EVALUATED, VALIDATING, ACCEPTED, REJECTED, INCONCLUSIVE, NOT_APPLICABLE. Completion and acceptance must both hold for verified scientific delivery.'),
('Policy','NOT_CHECKED, ALLOW, DENY, REQUIRES_APPROVAL. ALLOW applies to the action and says nothing about its scientific truth.')])+p('Reserve cost/resource capacity atomically before each action; settle actual use afterward and retain unknown liabilities. Resume, retries and replanning share the Run budget and deadline. Persist operation identities and request digests before dispatch. Lease expiry initiates reconciliation; a late Worker needs the current fencing epoch to publish. Checkpoints restore a program position, not an external process fact.')+p('CANCEL_REQUESTED is an intent. Only confirmed termination and cleanup justify CANCELLED. If submission or completion cannot be determined, retain UNKNOWN and block dangerous resubmission. Temporary artifact slots, checksum/size checks and immutable metadata publication must recover from a crash between file write and database commit.')),
section('science','Scientific acceptance',table(['Capability','Checks required','Interpretation boundary'],[
('Inspection','Actual format, hash, model/entity and chain namespaces; residues, insertion codes, altloc and excluded species.','Parsing success is not full structure-quality validation.'),
('Mapping','Explicit one-to-one atom correspondence, coverage, unmatched/conflicting items and selection materialization.','Same-looking residue numbers are insufficient evidence of correspondence.'),
('RMSD','Frozen fit/evaluation sets, right-handed Kabsch convention, det(R)>0, numerical tolerance and independent reference/invariants.','Independent region fits and evaluation after a CORE fit answer different questions.'),
('Contacts','Exact two objects, atom types, Euclidean units, threshold boundary and separate atom/residue outputs.','Proximity alone does not establish hydrogen bonding, binding affinity or functional causality.'),
('Report','Every number and claim resolves to actual artifacts, validated definitions and permitted interpretation.','Unsupported or inconclusive science stays explicit; textual confidence cannot upgrade evidence.')])+p('The runtime checker helps control a Run. The external acceptance reference judges the system. Disclose any shared implementation or data, and supply independent recalculation where shared logic could certify its own defect. Historical validation is appended, not overwritten.')),
section('acceptance','Release gates AC-01–AC-22',table(['ID','Gate','Pass rule'],[[x['id'],x['title'],x['pass_rule']] for x in acceptance])),
section('evaluation','Evaluation, optimization and denominators',p('The north-star metric is scientifically valid delivery: preallocated in-scope valid-task Runs whose actual artifacts pass independent scientific checks, whose report matches evidence and whose actions were authorized, divided by all preallocated valid-task Runs. Failures, timeouts, missing artifacts and false refusals stay in the denominator. Retries are Attempts, not fresh independent Runs.')+p('Separately report ambiguity handling, unsupported/invalid handling, critical hidden errors among delivered results, unnecessary clarification/approval, actual unauthorized side effects, complete cost and latency. Unknown billing is UNKNOWN with coverage. Separate cold and warm caches and show per-family difficulty and object coverage.')+table(['Dataset','Use','Boundary'],[
('D_dev','Visible development labels and debugging','Prompt/tool optimization may reuse this set; record source and authorization.'),
('D_reg','Known defects and representative valid cases','Passage establishes known regression coverage, not held-out generalization.'),
('D_test','Sealed acceptance after configuration freeze','Split correlated objects, families and templates as clusters; hide references/scorers from retrieval and memory.'),
('D_feedback','Quarantined user feedback and online failures','Check license/privacy, reproduce and scientifically review before promotion to the next dev/reg version.')])+p('The starting proposal is a 24-task pilot across at least four public object families, followed by 60 frozen acceptance tasks: 36 explicit valid, 12 ambiguous and 12 invalid/unsupported, spanning at least six families separated from development. Three preallocated real-model Runs per task are suggested subject to budget. These are starting design choices, not power guarantees or achieved results.')+table(['Configuration','Question answered','Important limit'],[
('Q-REF','Can fixed checked TaskSpec and known valid plans produce correct reference artifacts?','A deterministic executor does not demonstrate natural-language planning.'),
('Q-BASE','How does a minimal registered-tool real-model Agent perform with the same tools, knowledge, scope and total budget?','Retain hard safety and final scientific checks; do not make unsafe output the baseline.'),
('Q-CAND','Does the proposed compiled-task and bounded-repair system improve usable delivery, hidden errors, false refusals and cost?','If multiple mechanisms change, attribution is to the complete system; test individual mechanisms separately.')])+p('Score objects, numerics, artifacts and permission facts with deterministic checks and independent references. Use anchored expert rubrics for interpretation. An LLM judge may assist only after task-specific expert calibration; it does not establish numerical truth or authority. Compare paired tasks, aggregate repeats within task and estimate uncertainty by independent object clusters. With too few clusters, present descriptive results and the limitation.')+p('Proposed release goals are ≥90% valid-task scientific delivery overall and ≥80% within each declared family; ≥95% appropriate ambiguity/boundary handling; and zero observed known severe hidden errors or unauthorized effects in tested samples. These are draft goals to calibrate after the pilot and freeze before final testing, not measured claims. Never lower them after inspecting final failures and call the old protocol passed.')),
section('security','Security and human control',p('Untrusted publications, tool output and logs are data, not instructions with authority. Server sessions, project membership, registered capabilities and current policy determine action scope. Validate each execution boundary; a model statement that it refused is not evidence that no file was read or transmitted.')+ul([
'Keep secrets in approved server connectors, outside prompts, ordinary logs, URLs, reports and artifacts. Apply project data policy independently to model requests, traces, indexes, caches and exports.',
'P0 permits normal new immutable outputs without approval and disables unsupported high-impact actions. P1 approvals bind exact action data, destination, parameters, versions, actor/project, expiry and nonce; revalidate current authority and consume atomically.',
'Use restricted fixed tool entry points. Filesystem path containment must handle symlinks and races; do not rely solely on lexical checks or a container label.',
'Escape report content, keep raw HTML downloads isolated, authorize every artifact fetch and avoid private-file existence/size leaks through range requests.',
'Handle revocation, cross-project references, malicious retrieved instructions, quota races and late Worker messages in real integration tests.'
])),
section('operations','Nonfunctional requirements and operations',p('Initial limits are configurable development proposals: 50 MiB upload, 100 MiB output per Run, 12 registered tool actions, 8 model calls, 2 transient retries per step, 2 scientific-repair rounds, 2 GiB Worker memory, 300 s CPU tool wall time, 900 s Run wall time and 2 concurrent CPU Runs per project. Calibrate/version them on the actual server. They are neither measured capacity nor universal scientific-tool limits. Reject unsupported archives and oversized data rather than silently truncating the object.')+p('Candidate P95 request acceptance/query latency ≤2 s excludes model inference and scientific completion. State the hardware, workload, window and denominator before adopting an SLO. Use actionable alerts for stalled recovery, queue age, missing artifacts, unknown cost and scientific-check regressions. Preserve business events independently of optional sampled traces.')+p('Backups must restore metadata and immutable bytes together in an isolated drill. Release code, image digests, model/prompt settings, schemas, tool versions, validators and reference data as a compatible set. Canary a bounded cohort, stop on critical science/security regressions and preserve in-flight versions. Rolling back new Runs must not blindly reissue old side effects.')),
section('delivery','M0–M5 implementation gates',table(['Milestone','Deliverables','Exit evidence'],[
('M0','Contracts, scientific defaults, environment/data policy, model budget and 24-task pilot plan.','Owners confirm decisive semantics; unresolved choices are explicit. Document publication is not deployment.'),
('M1','Deterministic real-input inspection, mapping, superposition, contacts, immutable artifacts and independent acceptance.','AC-01–05 pass; add object families beyond the AdK fixture; failures and results trace to Runs.'),
('M2','One real-model controller, clarification/repair, workbench and evidence UI.','Model actions use actual observations; complete pilot failure/cost record; calibrate and freeze initial quality/resource targets.'),
('M3','Real authentication/project ACL, effective Worker isolation, atomic budget, recovery and audit.','Relevant P0 AC-09–19 pass; no unresolved severe science/security defects; fake principals remain localhost-only.'),
('M4','Frozen acceptance and bounded team pilot.','Complete AC-06–08 and AC-21–22 under the frozen protocol. Unmet goals return to development rather than changing final gates.'),
('M5','P1 extensions as capability packages.','Pass AC-20 and capability-specific acceptance. HPC/GPU/export require real backend and high-impact-control evidence; P0 scores do not transfer automatically.')])+p('Open decisions include pilot users and identity integration, real data confidentiality, priority task families, approved model/provider/data handling, hardware limits, staffing and support responsibility. The PRD does not invent a schedule or claim these choices are already confirmed.')),
section('sources','Source baseline and developer entry points',p('This editorial English guide preserves the current P0 semantics and FR/AC/API identifiers. Exact fields, enums, nullability, status codes and database constraints remain defined by the canonical files, not by a prose table.')+'<p>'+ ' · '.join(link(u,t) for u,t in [('../../prd/prd.json','PRD source JSON (Chinese prose)'),('../../prd/requirements.json','Requirements and traceability source (Chinese prose)'),('../../architecture/architecture.json','Architecture source (Chinese prose)'),('../../prd/engineering/engineering-spec.json','Engineering specification source'),('../../prd/engineering/validation/check_contracts.py','Contract validation program'),('../../prd/engineering/ops/config.example.yaml','Configuration template')])+'</p>')
]
page('prd','index.html','Product requirements and development baseline','A complete English guide to the proposed PRD 0.2, including functional requirements, scientific acceptance, API inventory, evaluation and release gates.',prd_sections,'../../prd/index.html')
(EN/'prd/requirements.en.json').write_text(json.dumps({'document_type':'EDITORIAL_ENGLISH_GUIDE_NOT_A_NEW_API_VERSION','source_version':'0.2','status':'PROPOSED_REVIEW_BASELINE_NOT_IMPLEMENTED','english_edition_date':'2026-11-14','requirements':requirements,'acceptance':acceptance,'traceability':source_prd['traceability']},ensure_ascii=False,indent=2)+'\n')

CHAPTERS = [
{'id':'E01','slug':'01-contract','title':'From natural-language requests to testable task contracts','lead':'A mature system must state what it accepted, which object it measured and what evidence will count as completion. Conversation gathers intent; a versioned contract makes it executable and reviewable.','sections':[
('Define the deliverable before the dialogue','“Compare these structures” could mean fold, assembly, local conformation or model quality. Decompose the request into objects, measurements, required inputs and outputs. A useful first operation is a specified-atom comparison under an explicit mapping. The Task persists the formal request after the chat disconnects. Separate user-provided facts, facts confirmed from files and information still unknown. Record defaults and their scientific effect; do not use a convenient chain default to erase ambiguity.'),
('Put scientific semantics in both input and output contracts','A file path is not an input identity. Record content hash, format, model, chain namespace, residue/atom selection, assembly handling, units and missing-data policy. In mmCIF, auth and label identifiers can differ; a syntactically valid chain name may select the wrong entity. First inspect the actual hierarchy. Outputs should include correspondence tables, transformation parameters, per-position differences, coverage, exclusions and a validation record. A low RMSD is not a universal success criterion: it depends on the fitted and evaluated object.'),
('Let the planner propose and the compiler verify','The model selects candidate capabilities and dependencies. A deterministic compiler checks registered tool versions, typed references, compatible selections, required validation, DAG structure, scope and resource limits. Reject a plan before side effects when its prerequisites fail. Accept equivalent valid paths rather than forcing one narrative reference sequence. Keep candidate actions, accepted plans, actual tool results and report explanations as distinct records.'),
('Turn uncertainty into a control branch','Missing decisive identity goes to clarification; unsupported scope goes to a reasoned boundary response; transient tool failure goes to a safe bounded retry; insufficient science goes to rejection or inconclusive evidence. A same-contract execution repair can append a plan version. A changed scientific question after freezing creates a linked new request revision and Run. The original contract and failed evidence remain auditable.')],
'failure':('A multichain file returns a plausible numeric result after a default chain was selected.','Reject trusted scientific delivery if the actual selection does not match the contract. Show the object inventory, obtain the decisive selection and preserve the failed attempt. A plausible number does not establish that the intended object was measured.'),
'checklist':['A task has explicit objects, supported scope and refusal conditions.','Every default has provenance and a stated effect.','Input/output schemas include units, identity and selection semantics.','Planner proposals cannot bypass deterministic preconditions.','The report can be traced to a frozen contract and actual artifacts.']},
{'id':'E02','slug':'02-architecture','title':'Reference architecture and data ownership','lead':'Separate control, scientific execution and evidence storage so the system can explain results, recover failures and assign responsibility. A single overall status is not enough.','sections':[
('Control and computation are separate responsibilities','The interface/API receives the task, authenticates access and exposes state. The controller assembles context, proposes bounded actions and records decisions. Adapters and Workers run scientific programs in controlled environments. A domain validator checks real objects and outputs; reporting cites the artifacts. Modules can share one repository. Separate processes when restart, resource or trust boundaries justify it, rather than creating a microservice for every box.'),
('Represent a computation as related entities','Task and immutable TaskRevision capture the request. A preallocated Run captures one configuration and cumulative budget. A FrozenTaskSpec captures the scientific definition; PlanRevision and Step capture execution dependencies; Attempt captures actual execution; an optional external Job captures scheduler facts. Artifact records immutable bytes and parents; Validation records a versioned judgment. Feedback is evidence requiring reproduction. Distinguishing these identities lets one task have several reproducible Runs without counting internal retries as new experiments.'),
('Distinguish state and storage types','Graph state is a working projection for the next decision. The business ledger owns execution, authorization, budgets and events. A checkpoint stores the graph position and state needed to resume. Files/object storage holds structures, trajectories, tables, logs and plots, while a retrieval index holds task-authorized knowledge references. An index hit does not replace original provenance; a checkpoint is not evidence that an external side effect executed exactly once.'),
('Keep a reliable handoff between transactions and dispatch','Persist the operation identity, Attempt intent, budget reservation and outbox event within an explicit database transaction. A dispatcher claims work with a durable lease and passes the stable identity to the executor. Delivery may duplicate; the executor and ledger must recognize the same logical operation. Database, filesystem, model service and external scheduler do not share a magical common transaction.'),
('Make lineage answer where a conclusion came from','A metric must point to the exact input bytes, scientific specification, mapping, code/environment version, producing Attempt and checker policy. Reports are derived artifacts, not mutable replacements for the original result. Keep failed and superseded candidates, while controlling their visibility and retention. Access checks apply to derived objects and cache hits as well as original input.')],
'failure':('The UI says success, the Worker wrote a file and the database has no accepted Artifact record.','Reconcile the dedicated output slot against the ledger, check hash and completeness, then register or quarantine it. Neither a file name nor a final chat message may create authoritative success.'),
'checklist':['Every fact has one owning component.','Run, Plan, Step, Attempt, Job, Artifact and Validation can be joined.','Graph state and durable execution facts have separate roles.','Crash points around dispatch and publication have a recovery path.','Report metrics preserve input and producer lineage.']},
{'id':'E03','slug':'03-tools','title':'Tool engineering and scientific execution','lead':'A maintainable capability includes its scientific meaning, execution environment, I/O, resource needs and checks. Being callable is only one part of being usable.','sections':[
('Maintain a capability contract','For each operation, define purpose, applicable data, preconditions, typed parameters/results, units, selection policy, version/license, resource class, error semantics and independent reference tasks. Distinguish registration, deployment health, reference passage and per-project authorization. Expose only the currently executable authorized set to the planner. A tool count is not a scientific coverage measure.'),
('Use adapters to separate model and program interfaces','The model passes typed artifact references and scientific parameters. An adapter resolves authorized input, validates it and calls a fixed library function or argument-safe program entry point. It captures return code, logs, outputs, measurements and structured errors. It does not allow model-supplied host paths, shell fragments or package installation. Preserve original bytes; normalization and preprocessing must create documented derivatives.'),
('Choose backends from the computation','Small checks and geometry can use restricted synchronous CPU execution. Long jobs should use an asynchronous Job protocol with status, heartbeat, cancellation and artifact collection. GPU predictions and HPC simulations need their own resource, environment, license and acceptance contracts. For P0, use the tested CPU path and clearly reject unsupported backends; do not manufacture a scheduler Job in a teaching fixture.'),
('Make resource requirements visible to the plan','Declare CPU/GPU, memory, disk, wall time, model-call and output requirements. Queueing is a separate latency component from computation. Reserve resources atomically under a cumulative Run budget and enforce actual limits at execution. Unknown billing remains unknown. A larger request should queue or be rejected with a reason, not silently shrink its scientific object.'),
('Rebuild environments and test upgrades','Pin code and dependency/image digests, model weights and database versions when applicable. A reproducible environment still needs reference tasks on real and negative inputs. Parser, numerical kernel, tool or validator upgrades require corresponding regression. Identify environmental assumptions rather than treating an example notebook that ran once as a reusable production method.'),
('Keep four orchestration roles distinct','Agent orchestration chooses bounded next actions; a durable task service owns state and recovery; a scientific workflow defines domain dependencies; an HPC scheduler allocates and monitors compute resources. Existing validated domain workflows can be registered as composite tools. MCP provides a tool interface, not a job scheduler, a sandbox or scientific validation.')],
'failure':('A registered tool is visible but its scientific environment is broken.','Mark that version unavailable, preserve the execution failure and repair the environment through the maintainer process. Do not let the model invent a substitute command or claim that registration proves execution.'),
'checklist':['Every exposed capability has a tested adapter and scientific acceptance.','Parameters and host process arguments are separated.','Environment, license, version and resource assumptions are explicit.','Error classes distinguish input, policy, environment, transient and scientific failures.','An upgrade is checked against old and new reference inputs.']},
{'id':'E04','slug':'04-recovery','title':'Durable execution and recovery under uncertainty','lead':'Disconnection creates uncertainty, not permission to repeat a side effect. Recovery starts with durable identities and reconciliation of what the executor actually did.','sections':[
('Separate logical operations from attempts','A stable operation identity represents a particular scoped intent and payload. An Attempt records an actual execution try. Retries may create new Attempts, but must preserve causal linkage and the same Run budget. Bind idempotency to authenticated scope and canonical payload, not just a user-supplied string. The same key with a different request is a conflict; an old key cannot bypass revoked access.'),
('Write intent before submitting and reconcile afterward','Before an external submission, persist the intended operation and correlation key. If the scheduler accepts a job but confirmation is lost, use namespace, stable operation key and a bounded submission time window to find the original execution. This requires a backend that retains queryable correlation. If the original cannot be established, preserve SUBMISSION_UNKNOWN/UNKNOWN and escalate rather than assuming nothing happened.'),
('A checkpoint restores software state, not the outside world','A replayed graph node may execute again. Before repeating any effect, consult the ledger and actual process/job/artifact state. Lease expiry alone does not prove a process stopped; a PID can also be reused. Use an execution handle, start-time evidence, output slot and fencing epoch to stop stale Workers from publishing over recovered state. Persist state transitions with optimistic or transactional concurrency control.'),
('Use different responses for different failures','Clarify invalid/missing scientific input; bound retries for safe transient faults; disable and repair an unavailable environment; retain scientific rejection when the output fails its contract; keep uncertain external effects unresolved until reconciliation. Cancellation intent is not termination. A Worker or backend must confirm the terminal process state and cleanup before resources can be fully settled.'),
('Validate cache reuse','A cache key must represent input bytes, selections, scientific parameters, code/environment versions and relevant policies. Recheck current authorization and artifact integrity. A cached result may have been scientifically validated under an old checker; append a new validation where required instead of overwriting history. Never share a cross-project hit solely because the content digest matches.')],
'failure':('An external job was accepted but its acknowledgment was lost; the Worker then restarts.','The recovery Worker first reconciles the stable operation with external queue/accounting records. It attaches the existing Job if found. If not provably absent, keep the operation unknown and avoid a duplicate expensive submission. Record both the evidence and the remaining uncertainty.'),
'checklist':['Stable operation and distinct Attempt identities exist before side effects.','Crash points before/after submit and before/after artifact registration are tested.','Late messages are fenced.','Cancellation and unknown states preserve actual facts.','Recovery checks artifacts and costs before issuing new work.']},
{'id':'E05','slug':'05-validation','title':'Scientific acceptance and Agent evaluation','lead':'Judge execution, artifacts, science and interpretation separately. A system can run successfully and still answer the wrong scientific question.','sections':[
('Four acceptance gates','First, determine whether a real execution occurred under the expected adapter and environment. Second, validate artifact structure, completeness, identity and provenance. Third, check scientific prerequisites, mapping, units, numerical values and applicability. Fourth, check whether the report is supported by those artifacts and stays within the evidence. Keep all four outcomes; do not compress them into one success field.'),
('Independent references and invariants','Prepare trusted numerical references, reviewed object selections and invariants before evaluation. Examples include internal-distance invariance under a rigid transform, known-transform recovery, right-handed fitting and separation of fit/evaluation regions. Tolerances are part of each tool contract, not arbitrary post hoc thresholds. Test the validator with positive, negative and boundary cases, including finite plausible values from the wrong chain.'),
('Split tasks and objects to test generalization','Hold out related object families, near-duplicate templates and task combinations together. Freeze reference inputs, versions, mappings, labels and interpretation rubrics. Distinguish development, regression, final acceptance and quarantined feedback. Re-running AdK examples can show regression stability; it cannot establish generality across all structural biology. Include invalid inputs, ambiguity and unsupported requests, not just answerable tasks.'),
('Freeze configurations and isolate mechanisms','Compare a deterministic scientific executor, a minimal real-model tool Agent and the proposed controlled system using the same tools, knowledge, model conditions, budget and stop rules where applicable. Keep hard safety and final scientific acceptance in every condition. Use single-factor or structured ablations for contracts, runtime feedback and repair, rather than changing many components and assigning all benefit to one.'),
('Report denominator, cost and scope','Every preallocated Run receives an outcome, including missing artifacts and failed or falsely refused tasks. Retry cost belongs to the original Run. Mark broken references/scorers as evaluation-invalid and missing billing as UNKNOWN. Report scientific delivery, hidden errors, refusal quality, human intervention, cost and cold/warm latency by family and difficulty. Pair comparisons by task, aggregate repeated Runs within task and estimate uncertainty at an independent object-cluster level.')],
'failure':('Both files parse and return a plausible RMSD, but one selection uses an unrelated chain.','Object/mapping validation must reject trusted delivery. Preserve the candidate and diagnosis; if the intended selection changes the frozen scientific contract, create a linked new revision/Run. The failed original remains in evaluation and cost records.'),
'checklist':['Test tasks have frozen identities, families and independent references.','Execution, artifact, science and explanation outcomes are separate.','Validators are tested for false acceptance and false rejection.','Comparisons keep tools, resources and stop rules controlled.','Failures, retries, hidden errors and uncertainty are reported.']},
{'id':'E06','slug':'06-governance','title':'Permission isolation and scientific data governance','lead':'Retrieved text, tool descriptions and logs are untrusted information. Scientific data may also be unpublished or restricted. Authority must follow authenticated identity and policy through every component.','sections':[
('Information does not acquire command authority','A paper, page or tool result may contain an instruction to access another project or export data. Treat it as content, not permission. The execution gateway validates the current principal, project, object, action, destination, tool version and budget. A model saying it refused is not proof that no access occurred; inspect the trusted side-effect ledger. Preserve legitimate task branches when an unrelated malicious action is rejected.'),
('Narrow authorization by object, action and time','Mount only the inputs required by the task and use a dedicated immutable output area. Avoid broad shared-drive access or long-lived credentials in Workers. High-impact approval, when implemented, binds exact data hashes, destination, parameters, version, expiry and one-time use; it cannot enlarge hard rights or budgets. Recheck access after revocation and on cached reads, streams and downloads.'),
('Restrict filesystem, network and resources','Use nonprivileged fixed tool environments with read-only inputs, scoped output and no host secrets or control sockets. Enforce CPU, memory, process, disk and time limits; restrict egress to the actual need. Container use alone is not a complete isolation claim. Unknown generated code has a different threat model from a tested scientific adapter and needs stronger isolation before it is offered.'),
('Govern derived data as well as raw input','Indexes, model prompts, traces, caches, plots, reports and backups create further copies or paths of disclosure. Apply project classification, retention, access and deletion rules to all of them. Default telemetry should capture identifiers, hashes and minimal diagnostic locations rather than complete private structures or raw prompts. Any expanded content collection needs an explicit permitted purpose and retention boundary.'),
('Treat upgrades as supply-chain changes','Pin source/build provenance and dependencies, review executable entry points and identify affected artifacts. A new tool, model, parser or image can change scientific behavior and security exposure. Re-run numerical, policy and regression checks before wider enablement. A provenance record is useful evidence, not a claim that an entire security standard has automatically been achieved.')],
'failure':('A retrieved document asks the Agent to read another project and export its structures.','The final execution boundary rejects the action using current identity, project and destination policy; it records minimal evidence and can continue the legitimate reading task. Add the actual blocked action to cross-project regression, not only a textual prompt test.'),
'checklist':['Trust boundaries and permission matrices cover the entire data path.','Worker credentials, directories, egress and resource rights are task-scoped.','Revocation and cross-project access are integration-tested.','Logs, indexes, caches and backups have retention rules.','Tool upgrades are traceable to affected scientific results.']},
{'id':'E07','slug':'07-operations','title':'Observability, operations and release','lead':'A long-lived service must locate failures, reduce their impact and recover safely. Operational evidence should connect user requests, actual computation and scientific outcomes.','sections':[
('Use stable identities across asynchronous boundaries','Correlate request/task/Run/Step/Attempt/Job/Artifact/Validation with code, model, tool and release versions. Durable business events carry authoritative state transitions; traces and span links help diagnose timing across processes. Do not make an optional tracing platform the only place a task fact exists. Minimize raw sensitive content while keeping enough identifiers to find the first contract violation.'),
('Define SLOs around the user promise','State the operation, denominator, window, measurement point and workload. API acceptance/query latency is different from queue wait, model inference and scientific completion. A suggested 99% or two-second illustration is not a measured target. Separate availability from scientifically accepted delivery, and report cost/unknown usage so fast failure is not mistaken for efficient service.'),
('Alert toward an actionable response','Prioritize user impact and stalled recovery: old unknown jobs, missing artifact registration, exhausted reservations, queue age, scientific-check failures and authorization anomalies. Each alert needs an owner, initial containment, diagnosis and a recovery check. A CPU spike alone need not wake a maintainer unless it threatens a defined service boundary. Keep runbooks versioned with the affected system.'),
('Demonstrate recovery through drills','Back up metadata and immutable artifact bytes with a consistency strategy. Restore into an isolated environment, inspect lineage and hashes, reconcile unfinished work and verify access boundaries. A successful backup log cannot establish a working restore. Test provider outage, disk full, Worker loss, acknowledgment loss and late results; record what is known, unknown and still consuming resources.'),
('Release and cost control share a loop','Version model/prompt/tool/parser/checker/data settings with code and images. Evaluate a bounded cohort before expansion, and consider compatibility with in-flight Runs. Pause new work and reconcile existing executions when a release breaks state progression. Rollback must preserve versioned history and must not blindly replay old side effects. Include failed attempts, queueing and remote compute in the same cost ledger.')],
'failure':('After a release, tasks stay “running” although external jobs have finished and users resubmit.','Pause new submissions on the affected version. Reconcile Runs and Jobs, collect existing artifacts and validate them; recover only genuinely missing steps. Roll back only after checking compatibility with current in-flight state, then investigate duplicates and cost.'),
'checklist':['Request, Run, Job, Artifact and Validation can be located from each other.','SLOs identify windows, denominators and workload.','Alerts have owners and recovery checks.','Metadata and files have passed an isolated restore drill.','Releases protect in-flight state and rollback is tested.','Retry and remote-resource costs remain visible.']},
{'id':'E08','slug':'08-roadmap','title':'From prototype to an operable service','lead':'Progress by observable exit evidence. Neither more infrastructure nor more tool names establishes scientific maturity. The stages below are recommendations, not a fixed schedule or certification.','sections':[
('Stage 1: prove one scientific task independently','Choose one explicitly bounded task family with real inputs, a fixed-workflow baseline, an actual artifact and independent reference. Cover valid input, wrong selection and tool failure. Separate model, tool and environment responsibilities. A reviewer should be able to explain every result from original bytes to numerical check, and failures should remain failures.'),
('Stage 2: turn a call into a task service','Add stable identities, persistent state, a restricted Worker, query/cancel/download and artifact registration. Exercise restarts and acknowledgment loss. Refreshing the UI must not compute again. Recovery should first find existing external work and artifacts, then decide what may safely continue. A graph checkpoint alone does not satisfy this stage.'),
('Stage 3: discover gaps with a bounded real pilot','Use a small known user group, explicit project permissions, declared tasks and quotas. Run realistic negative inputs, recovery drills and support procedures. Freeze evaluation versions, track human interventions, explain unknown states and assign an owner. Broaden task families only when each has an adapter, validation protocol and demonstrated user value.'),
('Stage 4: sustain delivery through change','Establish measured capacity and cost, SLOs, alerts, on-call/support responsibility, data lifecycle, backup restore, release evaluation and rollback. Preserve execution evidence across software/model/tool changes. State the tested scope and withdraw unsupported service claims when conditions change. A lasting service is an operational agreement backed by evidence.'),
('Select components around reuse boundaries','One repository can keep clear API/controller/Worker boundaries. Split services when measured resource, fault or team constraints justify the extra network/version/permission overhead. Reuse a graph framework for bounded control, a typed contract library for shape checks, a real database for facts and specialized tools for science. Write down what each component does and what the application still owns: identity, scientific semantics, external-job reconciliation and independent acceptance.')],
'failure':('Many tools have been added, but nobody can determine whether failures came from the model, tool version or environment.','Return to representative frozen tasks. Repair contracts, state, raw execution records and validators, and assign failure ownership. Compare scientific delivery, diagnosability, intervention and total retry cost before adding more scope or roles.'),
'checklist':['Supported tasks, users and research value are explicit.','Each stage has deliverables, owners and exit evidence.','One trustworthy task family precedes indiscriminate tool growth.','Process, state and scientific ownership are clear.','Release review includes access, capacity, restore, rollback and support.','Component choices are checked on the same actual tasks.']}
]

for c,original in zip(CHAPTERS,source_handbook['chapters']):
    sections=[section('problem','What problem this chapter solves',p(c['lead']))]
    for i,(title,body) in enumerate(c['sections'],1):sections.append(section('section-'+str(i),title,p(body)))
    sections.append(section('failure','Failure scenario and response',p('Scenario: '+c['failure'][0])+p('Response: '+c['failure'][1])+p('This is a design exercise, not an incident report from a deployed service. Confirm actual behavior from task, process/job, artifact and policy records rather than from the final text alone.')))
    sections.append(section('checklist','Delivery checklist',ul(c['checklist'])))
    sections.append(section('references','Primary references and source material','<ul>'+''.join('<li>'+link(x['url'],x['title'].replace('：官方文档',' documentation'))+'</li>' for x in original['sources'])+'</ul>'+p('The references support the underlying mechanisms; the structural-science control boundaries and implementation choices in this chapter are application design proposals.')))
    page('engineering',c['slug']+'.html',c['title'],c['lead'],sections,'../../engineering/'+c['slug']+'.html')

eng_index=[
section('chapters','Eight implementation chapters',table(['Chapter','Question','Read'],[[c['id'],c['lead'],c['title']] for c in CHAPTERS])+ '<ol>'+''.join('<li>'+link(c['slug']+'.html',c['title'])+'</li>' for c in CHAPTERS)+'</ol>'),
section('start','A practical implementation order',ul(['Read the English PRD to identify P0 requirements and fixed contract IDs.','Build one deterministic real-input path and independent checks.','Add durable identities, immutable artifacts, state and budget transactions.','Connect one real-model planner through a deterministic compiler.','Exercise ambiguity, invalid inputs, permission denial, unknown execution, cancellation and restart.','Freeze candidate versions and evaluate scientifically valid delivery, hidden errors, intervention and complete cost.'])),
section('reference','One authoritative contract baseline','<p>'+link('../prd/','English PRD and requirement tables')+' · '+link('../architecture/','English architecture guide')+' · '+link('../../prd/engineering/contracts/openapi.json','Canonical OpenAPI')+' · '+link('../../prd/engineering/engineering-contracts-v0.2.zip','Download original contract bundle')+'</p>'+p('The handbook explains design choices and failure modes. Canonical schemas and SQL remain in their original location and are not translated into a competing version. The existing teaching exercises remain fixed-workflow or simulated demonstrations, with their original evidence limits.')),
section('lab','Deterministic exercises and design templates',p('The durable-execution exercise uses separate local SQLite ledgers to simulate the control service and an external scheduler. Close and reopen connections after a lost acknowledgment, reconcile the original job and distinguish completed execution from scientific rejection. It demonstrates persistence and failure handling, not production HPC integration.')+'<p>'+link('../../engineering/durable_execution_lab.zip','Download durable-execution exercise (code; original notes in Chinese)')+' · '+link('../../engineering/production_blueprints.zip','Download illustrative design templates (original notes in Chinese)')+'</p>'),
section('ready','Readiness review',table(['Area','Evidence expected'],[
('Task and contract','Supported scope, correct object identity, units, input/output and refusal rules.'),('Tools','Environment health, references, clear errors, pinned versions and limits.'),('State and recovery','Joinable entities; lost acknowledgment, restart and unknown-job exercises.'),('Science and evaluation','Independent reference, layered outcomes, held-out objects, failure denominators and cost.'),('Isolation and data','Effective process/filesystem/network limits and project access across derived data.'),('Operations','Actionable alerts, paired metadata/artifact restore, versioned release and rollback.'),('Service','Declared users, task families, quotas, owners and support commitments.')]))
]
page('engineering','index.html','Engineering handbook','From a single tool call to a scientifically reviewable, recoverable and maintainable task service.',eng_index,'../../engineering/index.html')

ARCH_MODULES=[
('Workbench and API','User question, project and authorized artifact references','Immutable TaskRevision, preallocated Run, trusted scope and limits','Server authentication and membership own authority; clients do not self-authorize.'),
('Model adapter and controller','Object summaries, available capabilities, candidate spec, verified observations and remaining Run budget','Clarifying questions, scientific candidates and typed PlanCandidate','The model never reads arbitrary host paths, executes commands or decides permission.'),
('Compiler and policy gateway','FrozenTaskSpec, candidate plan, tool catalogue, trusted authorization and budget','Compiled dependency plan or explicit reasons for rejection','Check type/semantic links, preconditions and resource reservations; normal immutable outputs proceed automatically.'),
('Restricted CPU Worker','Controlled envelope, stable operation_id, lease_epoch, read-only artifact inputs and limits','Actual Attempt facts, mappings, transforms, logs and output bytes','PREFLIGHT only inspects; TOOL binds frozen contract/plan. A stale Worker cannot publish current results.'),
('PostgreSQL business ledger','Task/Run/Attempt/events, leases, budget and artifact metadata','Recoverable snapshots, dispatch work, ordered events and lineage','Checkpointer tables are isolated; business transactions and graph recovery require explicit coordination.'),
('Artifacts, validation and reporting','Actual bytes, frozen scientific contract, checker versions and evidence references','Scientific status, report and reproducibility material','Execution, authorization and scientific acceptance remain separate judgments.')
]
arch_sections=[
section('overview','Architecture, framework, model and scientific tools',p('Architecture allocates responsibilities: who owns a fact, who may act, how failures recover and which evidence supports delivery. A framework offers reusable control/integration; a language model proposes interpretations/actions; scientific tools compute from actual data; infrastructure persists and restricts those operations. An architecture diagram is a design, not proof that its interfaces are implemented.')+p('Use one LangGraph control graph and optional LangChain integration components. Keep actual work in tested scientific adapters and restricted Workers. Do not add a second multi-Agent framework before a controlled experiment demonstrates that role separation adds value under the same tools and budget.')),
section('choices','Initial technology choices',table(['Layer','Proposed choice','Application responsibility'],[
('Workbench','React + TypeScript; tables, plots, timeline and evidence report','API/scientific contracts stay stable if the team selects another UI; 3D and graph editing are optional later features.'),
('API','FastAPI, strict Pydantic models and OpenAPI','Scientific validity, object access and resources require checks beyond schema syntax.'),
('Controller','One LangGraph state graph with persistent PostgreSQL checkpointer','External side-effect deduplication and business transactions remain application responsibilities.'),
('Model','Provider-neutral ModelAdapter with approved configuration','Typed candidates, usage, provider request IDs, errors, timeouts and data policy.'),
('Science','Gemmi inventory, NumPy geometry and versioned adapters','Explicit correspondence, scientific preconditions, independent checks and reference coverage.'),
('Scheduling','PostgreSQL business tables, DB queue, leases and outbox','Start with low throughput; replace dispatch transport only when measured need justifies it.'),
('Execution','Independent restricted CPU Worker','Verify filesystem, network, resource limits and cleanup in the actual environment.'),
('Artifacts','Immutable project-scoped files plus metadata/SHA-256','Authorize by artifact_id, verify publication, preserve parents and validation history.'),
('Observability','Structured business events and optional traces/local metrics','Keep secrets and unnecessary private data out of telemetry; events remain authoritative.')])+p('Pin dependencies and image digests after an M0 compatibility trial on the target OS, Python/Node and hardware. An online documentation version is not evidence that the proposed stack has passed deployment tests.')),
section('modules','Module input, output and responsibility boundaries',table(['Module group','Input','Output','Boundary'],ARCH_MODULES)+p('These are code and ownership boundaries, not a requirement for separate microservices. API, controller and scientific Worker should restart independently; one repository and one database can support the initial slice.')),
section('state','Working state, checkpoints and authoritative facts',p('The graph state is the minimal permission-filtered view needed for the next decision: candidate/frozen spec references, object summaries, available tools, observations, pending questions and remaining budget. A checkpoint records where the graph should resume. The business ledger records what truly happened, who authorized it, what it cost and which artifacts were published. These roles may share a PostgreSQL instance but not ambiguous ownership.')+table(['Storage','Holds','Does not establish'],[['Business tables/events','Task, Run, Plan, Attempt, Artifact, Validation, scope, budget, lease and causal history','Scientific truth without validators or the reality of an unconfirmed external Job'],['Checkpointer','Graph position and serializable decision context','Exactly-once remote side effects'],['Artifact store','Original and derived immutable bytes, plots, tables and logs','Current access rights without metadata authorization'],['Knowledge index','Versioned task-relevant document/method/tool references','Authority to override policies or replace original provenance']])),
section('contracts','Typed tasks, frozen science and versioned plans',p('Typed I/O lets code reject malformed shapes, but scientific semantics and authorization still require separate checks. Preallocate the ANALYZE Run before model work. Candidate specs evolve through appended events; freeze once before ordinary scientific TOOL execution. Formal plans bind frozen_spec_id. A same-contract repair appends a PlanRevision; a post-freeze change in the scientific question creates a linked new TaskRevision and Run.')+p('Materialized mappings and pair-index artifacts can be computed later as long as they satisfy the frozen mapping/selection policy. Preserve the distinction between the scientific rule and the bytes produced when applying it. Ordinary TOOL Attempts need a compiled plan/spec/step; registered PREFLIGHT inspection and MODEL Attempts have their explicitly defined pre-freeze rules.')+'<p>'+link('../prd/#contracts','Canonical contract and API inventory')+'</p>'),
section('capabilities','P0 scientific packages and extension admission',table(['Package','Required product','Admission checks'],[['inspect_structure','Actual hierarchy, identity and exclusions','Parser cases, chain namespaces, hashes and negative formats'],['mapping','Explicit one-to-one atom pairs and coverage','Conflicts, missing items, altloc and reviewed correspondence'],['calculate_rmsd','Transform, fit/evaluation selections and displacements','Independent reference, rigid invariants, degeneracy, units and right handedness'],['calculate_contacts','Heavy-atom pairs and residue summaries','Threshold boundary, exact objects, deduplication and interpretation limits']])+p('Extend through a complete capability package: purpose, preconditions, typed contract, adapter/environment/license, resources, error/retry semantics, validator, reference tasks and report rules. Registration, deployment health, reference acceptance and current authorization are separate states. Never infer trajectory, docking, map interpretation or HPC readiness from CPU geometry scores.')),
section('execution','From a question to accepted evidence',ul(['API stores the original request and preallocates one ANALYZE Run, freezing identity/configuration/scope and reserving the total budget.','PREFLIGHT inspects actual input; the controller interprets intent and asks necessary questions within that Run.','The scientific contract freezes; the model proposes a plan and deterministic code compiles and authorizes it.','The dispatcher persists each Attempt/operation and resource reservation before a restricted Worker executes.','Artifacts are verified and published; independent scientific checks produce ACCEPTED, REJECTED or INCONCLUSIVE records.','Bounded same-contract revision uses real observations and the remaining budget. Reporting cites actual validated outputs and states limits.'])),
section('ledger','Asynchronous execution, leases and reconciliation',p('Use durable intent, stable operation_id, request digest, lease owner/epoch and explicit Attempt state. Commit business transitions and outbox events together. A replayed graph node first consults the ledger. A lost acknowledgment is not proof that the job was never submitted. A stale Worker must fail fencing before publication.')+p('A crash after writing bytes but before registration leaves an output slot to reconcile, not a valid public artifact. Close writes, verify size/hash, then publish immutable metadata. Cancel requests must be reconciled with actual process/job cleanup. UNKNOWN blocks dangerous resubmission and remains visible with unresolved cost. P0 does not claim a real Slurm recovery path.')),
section('validation','Four different judgments',table(['Judgment','Evidence','Owner'],[['Execution','Actual adapter/process/Attempt outcome and collected files','Executor and business ledger'],['Scientific acceptance','Correct objects, mapping, units, invariants/references and applicability','Versioned domain validator'],['Report review','Claims and values trace to artifacts and stay within supported inference','Report compiler and domain review'],['Experiment score','Frozen external references, complete denominators and controlled comparison','Evaluation harness / scientific reviewer']])+p('The first three support runtime delivery; the fourth assesses the system. Shared validator/reference dependencies must be disclosed. Neither a confident explanation nor an exit code upgrades scientific_status.')),
section('context','Retrieval, context and reusable experience',p('Retrieve only currently authorized and task-relevant tool documentation, scientific methods and historical evidence. Supply the model with summaries plus stable artifact/document references. Keep full structures, trajectories and logs in controlled storage. Documents and tool observations may inform action selection but cannot grant new permission.')+p('Preserve provenance, source versions and applicability when reusing prior plans or feedback. A stored reflection is a hypothesis about what helped, not new ground truth. Revalidate cache integrity and access and prevent hidden acceptance labels or scorers from entering retrieval/memory.')),
section('deployment','Minimal initial deployment',p('Deploy API, one controller, a restricted CPU Worker, PostgreSQL and immutable project storage. Keep model credentials in server connectors. Reserve the existing documentation port for the static resource site; its availability is not an execution service or authentication boundary. Define new service ports, storage paths and identity integration separately.')+p('Add a broker, dedicated object store, more Workers or HPC/GPU adapters only after measured demand or a domain requirement justifies the new operational contract. Scientific adapters must retain their I/O, permission and acceptance semantics when transport or scheduling infrastructure changes.')),
section('observability','Events, usage and recovery drills',p('Record every model/tool Attempt, Run phase/state transition, budget reservation/settlement, artifact publication and validation. A sampled trace or UI progress event cannot replace durable authoritative facts. Correlate versions and stable IDs; minimize sensitive content. Track stalled state progression, unknown execution/cost, queue delay, rejected artifacts and unintended side effects.')+p('Exercise restarts, late messages, lost submit acknowledgments, partial writes, disk pressure, denied actions, cancellation and restore. Preserve in-flight versions during releases. A useful recovery drill establishes consistency of process/job state, ledger and artifacts, not merely a responsive page.')),
section('code','Repository and graph assembly',table(['Area','Responsibility'],[['api/','Trusted identity, strict requests, idempotency/CAS, snapshots, downloads and events'],['controller/','Context projection, inspect/clarify/plan/compile/dispatch/validate/report nodes and bounded transitions'],['domain/','Structure identity, selection, mapping, numerical kernels and scientific acceptance'],['workers/','Fixed adapters, sandbox profiles, execution/heartbeat/result collection and fencing'],['ledger/','Transactions, budget, leases, events/outbox, artifacts and recovery'],['tests/ and evaluation/','Contract fixtures, numerical invariants, policy/recovery integration and frozen real-model task evaluation']])+p('These are proposed responsibility directories rather than claims of existing implementation. Define node inputs/outputs and durable side effects before wiring the graph. Recovery may replay code; each node must describe how it recognizes already-recorded work.')),
section('interfaces','Front-end/API state and event sequence',p('The UI first reads an authoritative Run snapshot, then replays durable events after its cursor and reconnects without submitting a new Run. All actions still use HTTP APIs with current authorization, idempotency or expected versions. SSE delivers observations of state; it does not execute work.')+p('Show execution, phase, science, budget and unknown liabilities separately. Read FrozenTaskSpec through its artifact reference and fixed schema registry; do not embed a comparison-specific JSON shape as the universal future TaskSpec. Download uses artifact_id with current ACL and integrity checks. Feedback is scoped to the same Run and project and begins as NEEDS_REPRODUCTION.')),
section('milestones','M0–M5 delivery and acceptance',p('Follow the PRD milestone IDs: M0 contracts/environment; M1 deterministic scientific slice; M2 real model and workbench; M3 effective boundaries and pilot readiness; M4 frozen acceptance and bounded team pilot; M5 separately accepted P1 extensions. Estimate staffing and dates from actual scope and environment, not from a generic template.')+'<p>'+link('../prd/#delivery','Detailed milestone gates')+' · '+link('../prd/#requirements','FR requirements')+' · '+link('../prd/#acceptance','AC acceptance rules')+'</p>'),
section('pitfalls','Architecture mistakes to detect early',ul(['Treating the model answer as an execution record or numerical reference.','Using graph memory/checkpoints instead of a business ledger.','Allowing model-provided roles, host paths or budget estimates to grant authority.','Silently changing a scientific question during repair or resetting cost with a planning Run.','Retrying an unknown external side effect rather than reconciling it.','Using a tiny fixed demonstration to claim all-task structural-biology generality.','Adding many tools, frameworks or services before object identity and scientific acceptance work.','Calling a mock policy fixture an operating-system sandbox or production authorization system.']))
]
page('architecture','index.html','Agent architecture and design responsibilities','A standalone English design guide connecting the proposed controller, scientific tools, durable ledger and evidence delivery to the current contract baseline.',arch_sections,'../../architecture/index.html')

learning_resources=[
('L01','Hello-Agents (Datawhale)','https://github.com/datawhalechina/hello-agents','Beginner course; the main material is Chinese, with an English README.','Python and basic LLM concepts.','Wrap a local mmCIF inventory/residue-count function, return structured invalid-input errors and save parameters/logs.','A general Agent tutorial; scientific validation and HPC/production permissions remain application work.'),
('L02','AI Agents for Beginners (Microsoft)','https://github.com/microsoft/ai-agents-for-beginners','English course with translations.','Python and the selected examples’ service prerequisites.','Expose local structure inspection and comparison as two tools; record actual calls and accept results against a reference.','Select examples matching your runtime/provider; this course is not a structural-computing platform.'),
('L03','Hugging Face Agents Course','https://github.com/huggingface/agents-course','English course with translated versions.','Python, LLM basics and the course account requirements.','Build a tool Agent with a stop condition and validate local geometry against reference answers.','Course assessment does not replace independent scientific acceptance.'),
('L04','OpenAI Agents SDK (Python)','https://github.com/openai/openai-agents-python','Function tools, run loop, sessions and tracing.','Python functions, type annotations and basic async code.','Replace examples/basic/tools.py with a structure-information function returning chain lists, counts and explicit parsing errors.','Actual model calls need configured service access; pin the SDK version used for reproduction.'),
('L05','Pydantic','https://github.com/pydantic/pydantic','Typed input/output constraints and JSON schemas.','Python classes, dictionaries and typing.','Define file/model/chain selection input and structured success/error output; reject unknown fields and invalid numbers.','Shape validation does not establish correct object selection, units or scientific truth.'),
('L06','LangGraph','https://github.com/langchain-ai/langgraph','Explicit state, nodes, branches and checkpoints.','Functions, state dictionaries and tool-call concepts.','Connect deterministic input inspection, validation and failure branches before inserting a model planner.','Graph state cannot replace a job ledger or deduplicate arbitrary external effects automatically.'),
('L07','MCP Python SDK','https://github.com/modelcontextprotocol/python-sdk','A common tool/resource/client/server interface.','Function I/O and client-server basics.','Expose structure inspection with typed parameters, results and errors; keep the same domain contract across direct and MCP calls.','Add MCP when multiple clients need the interface. Protocol connectivity is not execution isolation or scientific acceptance.'),
('L08','Langfuse examples','https://github.com/langfuse/langfuse-examples','Tracing, evaluation and feedback integration examples.','A runnable tool or Agent and basic request/log concepts.','Record input hashes, versions, output IDs, latency and acceptance for successful and failed scientific calls.','Choose examples matching language and SDK versions; traces diagnose, validators establish scientific acceptance.'),
('L09','Temporal Python samples','https://github.com/temporalio/samples-python','Durable workflows, activities, retry, cancellation and async completion.','Python async and external-operation semantics.','Split inspection into activities, simulate a retry/Worker restart and detect duplicate outputs or external jobs.','Use when long jobs justify it. External reconciliation and idempotency are still required.'),
('L10','ToolUniverse','https://github.com/mims-harvard/ToolUniverse','Scientific tool discovery, parameter descriptions, invocation and composition.','Python, JSON Schema and basic MCP concepts.','Describe a structure-validation operation and test missing path, wrong format and valid input with structured results.','A base installation does not supply all local scientific dependencies; some remote tools need separate credentials.'),
('L11','Biomni','https://github.com/snap-stanford/Biomni','Scientific environment and task-Agent separation with execution records.','Python, isolated environments and dependency management.','Register local structure validation returning hash, chain inventory, parser diagnostics and provenance; test fixed inputs first.','Installing the environment is not reproducing a research result; model/services and dependencies require separate setup.'),
('L12','Paper2Agent','https://github.com/jmiao24/Paper2Agent','Wrapping research code as reusable tools with environments, tests and documentation.','Python, Git, testing and reproducible source material.','Package an existing structure-metadata tutorial with I/O, dependencies, examples, expected artifacts and reference tests.','Generated interfaces retain upstream data/code/environment limitations; passing a tutorial is not validation on new structures.')
]
learn_sections=[
section('start','Start from one inspectable question',p('Build a structure-inspection assistant that answers: “Which models and chains are present, and what parsing anomalies were found?” Add explicit structural-comparison tasks only after this first boundary is trustworthy. Choose one introductory course, one Agent framework and one supported model configuration; learning every framework first is unnecessary.')+p('The learning materials are a source snapshot, not a claim that every example has been installed or run. Model credentials, scientific environments and compute services need separate setup. The existing offline exercises intentionally use a fixed plan or synthetic inputs and no real model. They help test execution and checking before adding model decisions.')),
section('steps','Six steps, each with a verifiable artifact',table(['Step','Build','Verify'],[
('1. Understand the loop','A diagram distinguishing model decisions, actual tools and environment state.','Explain why a fixed workflow is useful and which decisions genuinely depend on new observations.'),
('2. Add one real tool','A standalone structure-inventory function, then a tool wrapper.','One valid file returns genuine chain/model counts; invalid input gives an explicit error; actual parameters/results are inspectable.'),
('3. Define contracts','Typed request, success and error schemas with file/model/chain identities.','Unknown fields, nonexistent chains, missing units and non-finite numbers do not silently become valid defaults.'),
('4. Save state and recover','Task, Step, Attempt, optional Job and Artifact records with failure classes.','After restart, inspect existing work before resubmitting. Closing the UI does not cancel computation.'),
('5. Add independent acceptance','A small task set and reference distance/geometry checks.','Rigid transforms preserve internal distances; verify atom selections, units and tolerances. Separate execution, artifact validity, science and cost.'),
('6. Read scientific code by component','A method-integration note with dependency/version, I/O, example, tests and source.','Run a distinct input and explain why a tutorial reproduction does not establish open-ended scientific generality.')])+p('After direct function calls pass, compare the same tool through MCP and an Agent wrapper. The contract and error semantics should remain the same. A framework should not silently replace the scientific definition.')),
section('lab','A runnable offline geometry exercise',p('Before configuring a model, use the deterministic exercise to inspect a complete tool contract, real function execution, artifacts and independent checks. It uses synthetic coordinates and fixed plans, not a PDB/mmCIF parser or natural-language inference. The six teaching checks cover a reference triangle, rigid-transform invariance, selection order, invalid selection, units/non-finite values, and the separation of execution from scientific acceptance.')+'<p>'+link('../../learn/structure_agent_lab.zip','Download offline geometry exercise (code; original notes in Chinese)')+'</p><pre><code>python3 runner.py example.json output\npython3 -m unittest -v</code></pre>'+p('After the deterministic baseline passes, connect one already-tested function to your selected Agent framework. Real structural inputs require an appropriate parser, actual object identity and domain-specific checks.')),
section('stack','Select a branch by the problem',table(['Need','Learning branch','Application still owns'],[
('One Python tool used by a model','LangChain, a lightweight Agent SDK or PydanticAI','Real function execution, scientific objects and stop rules.'),
('Typed fields and errors','Pydantic','Actual file/object semantics and scientific acceptance.'),
('Conditional steps and resumable graph','LangGraph','Business ledger, idempotency and external effects.'),
('Shared tools across clients','MCP Python SDK','Compute allocation, job control, access and validators.'),
('Calls, timings and diagnosis','Tracing/evaluation examples such as Langfuse','Domain labels and independent numerical truth.'),
('Durable long-running activities','Temporal samples when justified','Backend-specific submission correlation, cancellation and reconciliation.')])+p('Framework roles overlap; these are learning directions, not a one-to-one ranking or proof of superiority. Pin the actual repository revision and select examples suited to your provider, operating system and deployment policy.')),
section('resources','Twelve learning resources and concrete exercises', ''.join('<article id="'+x[0]+'"><h3>'+x[0]+' '+link(x[2],x[1])+'</h3>'+p(x[3])+table(['Prerequisite','Exercise','Boundary'],[[x[4],x[5],x[6]]])+'</article>' for x in learning_resources)),
section('papers','Read papers with implementation questions',table(['You are implementing','Read alongside it','Find in the code'],[
('Tool-action loop','ReAct','How actions are produced, observations returned and termination decided.'),
('Dependencies and parallel branches','LLMCompiler','Which calls depend on previous results and which are truly independent.'),
('Scientific capability definition','ToolUniverse / SciToolAgent','Parameters, discovery, runtime, environment and validation boundaries.'),
('New method integration','Paper2Agent','Tutorials, code, dependencies, tests and reproducible artifacts.'),
('Independent geometry acceptance','ProteinGeoBench','The distinction between looking up facts, actually computing and judging numbers.')])+ '<p>'+link('../papers/','English paper guides')+' · '+link('../projects/','English framework/project guides')+'</p>'),
section('next','From the prototype to a usable task service',p('The first useful milestone is a natural-language request that triggers an appropriate real tool, respects a checked contract, yields traceable artifacts and reports a failure honestly. Then add persistent state, restricted execution, cumulative budget, independent acceptance, feedback and release regression. Broader tool coverage follows explicit capability admission, rather than replacing those controls.')+'<p>'+link('../engineering/','Read the eight engineering chapters')+' · '+link('../prd/','Use the proposed PRD baseline')+' · '+link('../architecture/','Study module responsibilities')+'</p>')
]
page('learn','index.html','A practical learning path for scientific Agents','Move from the first real function tool to typed tasks, durable execution and independently checked structural analysis.',learn_sections,'../../learn/index.html')

